import Foundation

// PWA 用的靜態資源(圖示為程式產生的 PNG,以 base64 內嵌)。
enum PWA {
    static let icon192 = Data(base64Encoded: "")!
    static let icon512 = Data(base64Encoded: "")!
    static let iconMaskable512 = Data(base64Encoded: "")!

    /// iOS 的 apple-touch-icon(滿版 180x180)。內嵌在網頁裡,因為 iOS 由系統另外下載圖示,
    /// 自簽憑證下那個下載會失敗,圖示就不會出現。
    static let appleTouchIconBase64 = ""

    static let manifest = """
    {
      "id": "/",
      "name": "Parallels Remote",
      "short_name": "Parallels",
      "description": "遠端控制 Mac 上的 Parallels 虛擬機",
      "start_url": "/",
      "scope": "/",
      "display": "standalone",
      "orientation": "portrait",
      "background_color": "#2E2F31",
      "theme_color": "#2E2F31",
      "icons": [
        { "src": "/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any" },
        { "src": "/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any" },
        { "src": "/icon-maskable-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable" }
      ]
    }
    """

    /// 最精簡的 service worker:不快取任何東西(API 回應永遠要即時),只是讓瀏覽器把網頁視為可安裝。
    static let serviceWorker = """
    self.addEventListener('install', () => self.skipWaiting());
    self.addEventListener('activate', e => e.waitUntil(self.clients.claim()));
    self.addEventListener('fetch', () => {});
    """
}
